SourceCode.Declaration:
/// <summary>
/// Component to add journal Id to headers
/// </summary>
class MwmsLogicComponentInventoryJournalId extends TFMLogicComponent
{
}

Method.Source:
/// <summary>
/// Header fields this component may require
/// </summary>
/// <returns>A MobReferenceDataConfiguration if header fields are needed, otherwise null can be returned</returns>
public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    refCon = super();
    refCon.addCollector(TFMGetReferenceData::defaultJournalIdCollector(0, extendedTypeStr(JournalId), true, extendedTypeStr(InventJournalId)));
    return refCon;
}

public static MwmsLogicComponentInventoryJournalId Construct()
{
    return new MwmsLogicComponentInventoryJournalId();
}

/// <summary>
/// Method that tells which request Class it's data can be parsed into
/// </summary>
/// <returns>The name of the request class the components data can be parsed to</returns>
public ClassName requestClassProvided()
{
    return classStr(TFMRequestItemAndDimensionElement);
}

public Common provideDataIfPossible(Common _table)
{
    Common ret;

    ret = super(_table);

    if (_table.TableId == tableNum(InventJournalTable))
    {
        ret = this.initInventJournalTable();
    }

    return ret;
}

/// <summary>
/// Method to initialize a new InventJournalTable
/// </summary>
/// <returns>An InventJournalTable buffer</returns>
protected InventJournalTable initInventJournalTable()
{
    InventJournalId                     inventJournalId;
    TFMRequestItemAndDimensionElement   docRequest = subComponents.getComponent(classStr(TFMLogicComponentDimensions)).componentRequest(request);
    inventJournalId                 = docRequest.parmJournalId();
    // Find the journal to add a line to
    InventJournalTable                  inventJournalTable = InventJournalTable::find(inventJournalId,true);
    // Calculate the number of lines
    inventJournalTable::initTotal(inventJournalTable);

    return inventJournalTable;
}
